export const DESTINATIONS: Destination[] = stateRows.flatMap(([state, region, imageIndex, entries, latitude, longitude]) =>
  entries.map(([name, categories, travelStyles, description, bestTime, location], index) => {
    const baseSlug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
    const slug = baseSlug === "dzukou-valley" ? `${baseSlug}-${state.toLowerCase().replace(/[^a-z]+/g, "-")}` : baseSlug;
    const image = DESTINATION_IMAGES[name] ?? `/placeholders/${slug}.svg`;
    return {
      id: `${slug}-${state.toLowerCase().replace(/[^a-z]+/g, "-")}`,
      slug,
      name,
      classification: CLASSIFICATION_BY_NAME[`${state}|${name}`] ?? "Lesser-known",
      state,
      region,
      categories,
      travelStyles,
      seasons: bestTime.includes("Monsoon") || bestTime.includes("July") ? ["Monsoon", "Autumn"] : ["Winter", "Spring"],
      description,
      whyHidden: `A more local, slower alternative to the famous ${state} circuit, best discovered with time, curiosity and a respectful pace.`,
      bestTime,
      location,
      difficulty: categories.includes("Adventure") || categories.includes("Mountains") ? "Moderate · local guidance recommended" : "Easy · suitable for a slow escape",
      activities: [...categories.slice(0, 2), ...travelStyles.slice(0, 2), "Local food", "Photography"],
      latitude: latitude + index * 0.12,
      longitude: longitude + index * 0.1,
      image,
      gallery: [image, image, image],
    } satisfies Destination;
  }),
);

export const STATES = Array.from(new Set(DESTINATIONS.map((destination) => destination.state))).sort();
export const REGIONS: Region[] = ["North India", "South India", "East India", "West India", "Northeast India", "Northwest India", "Southeast India", "Southwest India"];
export const CATEGORIES = Array.from(new Set(DESTINATIONS.flatMap((destination) => destination.categories))).sort();
export const MOODS = [
  { label: "I want peace", value: "Peaceful", icon: "leaf" },
  { label: "I want mountains", value: "Mountains", icon: "mountain" },
  { label: "I want water", value: "Water", icon: "waves" },
  { label: "I want adventure", value: "Adventure", icon: "compass" },
  { label: "I want photography", value: "Photography", icon: "camera" },
  { label: "I want a village escape", value: "Village", icon: "home" },
  { label: "I want stars", value: "Offbeat", icon: "sparkles" },
];

export function getDestination(slug: string) {
  return DESTINATIONS.find((destination) => destination.slug === slug);
}

export function searchDestinations(query: string) {
  const normalized = query.trim().toLowerCase();
  if (!normalized) return DESTINATIONS;
  return DESTINATIONS.filter((destination) =>
    [destination.name, destination.state, destination.region, ...destination.categories, ...destination.travelStyles, destination.description]
      .join(" ")
      .toLowerCase()
      .includes(normalized),
  );
}

